mapper.select:
select supply.*, user.name as supplierName, category.name as categoryName from supply
left join user on supply.supplier_id = user.id
left join category on supply.category_id = category.id

     and supply.product_name like concat('%', #{productName}, '%')
     and supply.category_id = #{categoryId}
     and supply.origin_province = #{originProvince}
     and supply.supplier_id = #{supplierId}
     and supply.status = #{status}

order by supply.id desc

mapper.update:
update supply set supplier_id = #{supplierId}, product_name = #{productName}, category_id = #{categoryId},
img = #{img}, origin_province = #{originProvince}, origin_place = #{originPlace}, unit = #{unit}, price = #{price}, total_quantity = #{totalQuantity}, quantity = #{quantity},
available_time = #{availableTime}, contact = #{contact}, status = #{status}, create_time = #{createTime}
where id = #{id}
